export function evaluate({inputs,time}){
const u=inputs.launchSpeed,g=inputs.gravity;
const T=u/g,H=u*u/(2*g);
const t=Math.min(time,2*T);
const yt=u*t-g*t*t/2;
const vt=u-g*t;
const rel=t>=T;
const tau=Math.max(0,t-T);
const yd=rel?H-g*tau*tau/2:H;
const vd=rel?-g*tau:0;
const ad=rel?-g:0;
const base=360,sc=230/2.2;
const Y=h=>base-h*sc;
const o=[];
o.push(...sdk.panel({id:'lane.toss',x:20,y:40,w:300,h:350,title:'Toss',state:t<=0?'At launch':(t<T?'Rising':(t===T?'At the top':(t<2*T?'Falling':'At launch height')))}));
o.push(...sdk.panel({id:'lane.drop',x:330,y:40,w:300,h:350,title:'Drop',state:!rel?'Held in place':(t===T?'Just released':(t<2*T?'Falling together':'At launch height'))}));
const cx1=170,cx2=480;
o.push(...sdk.groundMark('mark.launch',cx1,base+14,120,'launch'));
o.push(...sdk.groundMark('mark.launch2',cx2,base+14,120,'launch'));
o.push(...sdk.gate('gate.drop',cx2,Y(H)+18,{open:rel,w:50}));
if(rel)o.push(sdk.circle('ghost.drop',cx2,Y(H),24,{opacity:0.25}));
o.push(sdk.circle('ball.toss',cx1,Y(yt),24));
o.push(sdk.circle('ball.drop',cx2,Y(yd),24));
o.push(...sdk.vector('vec.v.toss',{x:cx1-30,y:Y(yt)},{value:vt,direction:'up'},{scale:12,label:'v',role:'observed'}));
o.push(...sdk.vector('vec.a.toss',{x:cx1+30,y:Y(yt)},{value:-g,direction:'up'},{scale:5,label:'a',role:'warning'}));
o.push(...sdk.vector('vec.v.drop',{x:cx2-30,y:Y(yd)},{value:vd,direction:'up'},{scale:12,label:'v',role:'observed'}));
o.push(...sdk.vector('vec.a.drop',{x:cx2+30,y:Y(yd)},{value:ad,direction:'up'},{scale:5,label:'a',role:'warning'}));
o.push(...sdk.callout(cx1+60,Y(yt)-30,['v '+sdk.format(vt,2)+' m/s','a '+sdk.format(-g,1)+' m/s^2'],{id:'callout.toss'}));
o.push(...sdk.callout(cx2+60,Y(yd)-30,['v '+sdk.format(vd,2)+' m/s','a '+sdk.format(ad,1)+' m/s^2'],{id:'callout.drop'}));
return {frame:{width:640,height:420,objects:o,readouts:[{id:'tossedVelocity',value:vt},{id:'tossedAcceleration',value:-g},{id:'dropVelocity',value:vd},{id:'dropAcceleration',value:ad}]},quantities:{launchSpeed:u,gravity:g,apexTime:T,apexHeight:H,tossedVelocity:vt,tossedAcceleration:-g,tossedHeight:yt,dropVelocity:vd,dropAcceleration:ad,dropHeight:yd}};
}
